collectors.eur_usd:
const r = await fetch('https://api.frankfurter.app/latest?from=EUR&to=USD');
        const j = await r.json();
        if (!j.rates || !j.rates.USD) throw new Error('no rate');
        return Math.round(j.rates.USD * 10000) / 10000;

collectors.gbp_usd:
const r = await fetch('https://api.frankfurter.app/latest?from=GBP&to=USD');
        const j = await r.json();
        return j.rates && j.rates.USD ? Math.round(j.rates.USD * 10000) / 10000 : null;

collectors.jpy_usd:
const r = await fetch('https://api.frankfurter.app/latest?from=JPY&to=USD');
        const j = await r.json();
        return j.rates && j.rates.USD ? Math.round(j.rates.USD * 100000) / 100000 : null;

collectors.temp_stockholm:
const r = await fetch('https://api.open-meteo.com/v1/forecast?latitude=59.33&longitude=18.07&current=temperature_2m');
        const j = await r.json();
        if (!j.current || j.current.temperature_2m === undefined) throw new Error('no temp');
        return j.current.temperature_2m;

collectors.wind_stockholm:
const r = await fetch('https://api.open-meteo.com/v1/forecast?latitude=59.33&longitude=18.07&current=wind_speed_10m');
        const j = await r.json();
        return j.current && j.current.wind_speed_10m !== undefined ? j.current.wind_speed_10m : null;

collectors.ethereum_release:
const r = await fetch('https://api.github.com/repos/ethereum/go-ethereum/releases?per_page=1', {
          headers: { 'user-agent': 'VolatiAI/1.0', 'accept': 'application/vnd.github+json' }
        });
        const j = await r.json();
        if (!Array.isArray(j) || !j[0]) throw new Error('no release');
        return { id: j[0].id, title: j[0].name || j[0].tag_name, published_at: j[0].published_at };
